export const topicGlossary = {
  "CPU Scheduling": [
    ["ready queue", "The set of processes that are in memory, able to run, and waiting for CPU time."],
    ["dispatcher", "The kernel component that hands the CPU to the process selected by the scheduler."],
    ["preemption", "Taking the CPU from a running process before its current CPU burst is finished."],
    ["time quantum", "The maximum CPU interval a process may use in one Round Robin turn."],
    ["context switch", "Saving one process's execution state and restoring another's; useful work pauses while this happens."],
    ["starvation", "Indefinite postponement when a policy repeatedly favors other runnable processes."],
  ],
  "Disk Scheduling": [
    ["seek", "Movement of a mechanical disk's read/write head to a requested track or cylinder."],
    ["cylinder", "The set of tracks at the same radius across a disk's recording surfaces; labs use it as a position number."],
    ["request queue", "Pending disk I/O requests waiting to be selected for service."],
    ["sweep", "A directional pass across disk positions used by SCAN-like scheduling policies."],
    ["starvation", "A request can wait for an unbounded time when the policy repeatedly selects other requests."],
    ["wrap", "The modeled travel from one end of the disk range to the other in a circular sweep policy."],
  ],
  "Memory Management": [
    ["free block", "An available contiguous region that can be considered for a new allocation."],
    ["partition", "A region of memory assigned to a process or managed as an allocation unit."],
    ["First Fit", "Select the first free block, in scan order, that is large enough for the request."],
    ["Best Fit", "Select the smallest free block that can satisfy the request."],
    ["Worst Fit", "Select the largest free block that can satisfy the request."],
    ["Next Fit", "Continue the next search from the position following the previous allocation, wrapping when needed."],
  ],
  "Memory Management Techniques": [
    ["partition", "A region of physical memory reserved for one process or allocation."],
    ["page", "A fixed-size unit into which a virtual address space is divided."],
    ["frame", "A fixed-size unit of physical memory that can hold one page."],
    ["page table", "Per-process mapping metadata that records where virtual pages reside and their access permissions."],
    ["segment", "A variable-sized logical region, such as code or stack, described by a base and a limit."],
    ["virtual address", "An address generated by a process and translated by the memory-management hardware."],
  ],
  "Page Replacement": [
    ["page fault", "An exception raised when a process references a page that is not currently mapped as resident."],
    ["frame", "A fixed-size physical-memory slot that holds a resident page."],
    ["locality", "The tendency of a program to reuse recently accessed data or access nearby addresses."],
    ["victim page", "A resident page selected for eviction to make room for a different page."],
    ["reference bit", "A hardware- or software-maintained indicator that a page has been accessed recently."],
    ["working set", "The pages a process is actively using over a chosen recent interval."],
  ],
  Deadlock: [
    ["Allocation", "The resources currently held by each process in a resource-allocation model."],
    ["Maximum", "The declared upper bound on the resources a process may request in the Banker's model."],
    ["Need", "The remaining resource claim, calculated as Maximum minus Allocation."],
    ["Available", "The count of resource instances that are free and can be allocated now."],
    ["safe sequence", "An ordering in which each process can finish with available resources plus releases from earlier finishes."],
    ["circular wait", "A cycle of processes where each waits for a resource held by the next process in the cycle."],
  ],
  "File Management": [
    ["file metadata", "Information describing a file, such as its size, ownership, permissions, and storage mapping."],
    ["logical block", "A block position within a file, independent of where its data is stored physically."],
    ["physical block", "A storage-device block that holds file data or filesystem metadata."],
    ["contiguous allocation", "Store a file's data blocks in consecutive physical locations."],
    ["linked allocation", "Connect a file's scattered data blocks with pointers from one block to the next."],
    ["index block", "A metadata block that records the physical locations of a file's data blocks."],
  ],
  "Process Synchronization": [
    ["race condition", "A result that depends on the timing or interleaving of concurrent accesses to shared state."],
    ["critical section", "The part of a program that accesses shared data and therefore needs coordination."],
    ["mutex", "An ownership-based lock that allows one thread at a time into a protected region."],
    ["semaphore", "A counter manipulated by atomic wait and signal operations to manage permits or ordering."],
    ["bounded buffer", "A finite-capacity queue shared by producers and consumers."],
    ["starvation", "A participant is continually bypassed and does not receive a resource or turn."],
  ],
  "Paging & Segmentation": [
    ["virtual address", "The process-visible address that must be translated before physical memory access."],
    ["page number", "The high-order part of a paged address used to index the page table."],
    ["offset", "The position within a page or segment; paging preserves it during translation."],
    ["frame", "A physical-memory slot of the same size as a virtual-memory page."],
    ["segment base", "The starting physical address recorded for a segment."],
    ["TLB", "A small cache of recent virtual-page-to-physical-frame translations."],
  ],
  "Hierarchical File Organization": [
    ["root", "The top-level directory from which an absolute path begins."],
    ["directory entry", "A name-to-object mapping held in a directory."],
    ["absolute path", "A path resolved from the namespace root rather than the current directory."],
    ["relative path", "A path resolved from the process's current working directory."],
    ["current directory", "The directory used as the starting point for relative path resolution."],
    ["path component", "One name in a path, looked up in the directory reached by the previous component."],
  ],
  "System Calls": [
    ["user mode", "A restricted CPU privilege level in which applications normally execute."],
    ["kernel mode", "A privileged CPU level in which the operating-system kernel can perform protected operations."],
    ["system-call interface", "The defined entry point through which a program requests a kernel service."],
    ["trap", "A controlled synchronous transfer of execution to a kernel handler."],
    ["argument validation", "Kernel checks of caller-provided values, memory references, and permissions before service."],
    ["return value", "The result or error indicator returned to the calling program after a service completes."],
  ],
  "OS Concepts": [
    ["kernel", "The privileged core that manages resources and enforces the operating system's protection rules."],
    ["process", "A running program together with its execution state, address space, and managed resources."],
    ["thread", "A schedulable execution stream that shares its process's address space and resources."],
    ["interrupt", "An event signal that makes the CPU pause its current flow and run an appropriate handler."],
    ["system call", "A controlled request by an application for an operating-system service."],
    ["device driver", "Kernel or system software that translates general I/O requests into device-specific operations."],
  ],
};

